effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float y = uv.y * density + acTime * roll;
  float s = 0.5 + 0.5 * sin(y * 6.2831853);
  float m = mix(1.0 - strength, 1.0, s);
  c *= mix(1.0, m, mixAmt);
  gl_FragColor = vec4(c * src.a, src.a);
}
